-- SAIF / LSIF Dev v0.26A.1.8
-- Generated exact/native and SAIF-overlay service point staging rows.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;
SET @offline_session_key := _utf8mb4'ecbbfa867b491c93570b92e0c6d3ff34e1e916da9df914d83edb066c1eac52c3' COLLATE utf8mb4_unicode_ci;
SET @offline_session_id := (SELECT id FROM offline_import_sessions WHERE session_key COLLATE utf8mb4_unicode_ci=@offline_session_key COLLATE utf8mb4_unicode_ci LIMIT 1);
SET @service_resolver_version := _utf8mb4'saif_service_point_resolver_v0.26A.1.8' COLLATE utf8mb4_unicode_ci;
DELETE FROM offline_interior_service_points WHERE session_id=@offline_session_id AND resolver_version=@service_resolver_version;
UPDATE offline_interior_apply_plan p JOIN offline_interior_service_points sp ON sp.plan_id=p.id AND sp.resolver_version=@service_resolver_version SET p.service_point_id=sp.id,p.service_resolver_version=@service_resolver_version,p.service_resolution_method=sp.resolution_method,p.service_confidence=sp.confidence,p.service_point_status=IF(sp.resolution_method='scm_exact','scm_exact','overlay_review'),p.apply_readiness=IF(sp.resolution_method='scm_exact','dry_run_ready','service_overlay_review') WHERE p.session_id=@offline_session_id AND p.plan_version='saif_enex_pair_planner_v0.26A.1.7' AND p.apply_readiness<>'blocked_duplicate';
UPDATE offline_interior_apply_batches b SET b.dry_run_ready_count=(SELECT COUNT(*) FROM offline_interior_apply_plan p WHERE p.batch_id=b.id AND p.apply_readiness='dry_run_ready'),b.service_pending_count=(SELECT COUNT(*) FROM offline_interior_apply_plan p WHERE p.batch_id=b.id AND p.apply_readiness='service_overlay_review'),b.exact_service_count=(SELECT COUNT(*) FROM offline_interior_apply_plan p WHERE p.batch_id=b.id AND p.service_point_status='scm_exact'),b.overlay_review_count=(SELECT COUNT(*) FROM offline_interior_apply_plan p WHERE p.batch_id=b.id AND p.service_point_status='overlay_review'),b.blocked_count=(SELECT COUNT(*) FROM offline_interior_apply_plan p WHERE p.batch_id=b.id AND p.apply_readiness='blocked_duplicate') WHERE b.session_id=@offline_session_id AND b.plan_version='saif_enex_pair_planner_v0.26A.1.7';
COMMIT;
SELECT COUNT(*) AS service_rows,SUM(resolution_method='scm_exact') AS scm_exact,SUM(resolution_method='saif_overlay_translated') AS overlay_review,SUM(enabled=1) AS enabled_should_be_zero,SUM(apply_status<>'draft') AS nondraft_should_be_zero FROM offline_interior_service_points WHERE session_id=@offline_session_id AND resolver_version=@service_resolver_version;
